from kern import Bau

B = Bau("daten.kennwerte", "M6 3", {
    "mittelwert": "Die Übungen berechnen den Mittelwert aus einer gegebenen Liste.",
    "mittel_rueckwaerts": "Die Übungen suchen einen fehlenden Wert mit einfachen Standardzahlen.",
})
ZF = "In welcher Zeile steckt der erste Fehler, und "

# ---------------- mittelwert ----------------
B.zahl("mittelwert", "test", 3, "umkehr", "umkehren",
       "Fünf Zahlen werden jeweils verdreifacht und danach um 4 verkleinert. Die fünf neuen Zahlen haben den Mittelwert 26. Wie groß war der Mittelwert der fünf ursprünglichen Zahlen?",
       10, "(26 + 4) : 3",
       [(22, "26 − 4", "die Verkleinerung um 4 falsch herum rückgängig gemacht und das Verdreifachen vergessen"),
        (30, "26 + 4", "die Verkleinerung rückgängig gemacht, aber nicht durch 3 geteilt")],
       "Der Mittelwert folgt denselben Rechenschritten wie jede einzelne Zahl. Rückwärts: Zuerst die Verkleinerung um 4 rückgängig machen, 26 + 4 = 30, dann das Verdreifachen: 30 : 3 = 10. Probe mit fünf Zahlen 10: neue Zahlen 3 · 10 − 4 = 26.")
B.auswahl("mittelwert", "korrektur", 2, "begruenden", None,
          "In einer Klasse mit 20 Kindern haben 16 Kinder im Mittel 10 € gespart. Die übrigen 4 Kinder haben nichts gespart. Wie viel Euro hat ein Kind der Klasse im Mittel gespart?",
          ["Im Mittel 8 €, denn die gesamten 160 € werden auf alle 20 Kinder verteilt.",
           "Im Mittel 10 €, denn Kinder ohne Erspartes zählen beim Mittelwert nicht mit.",
           "Im Mittel 6 €, denn die 4 Kinder ohne Erspartes senken den Mittelwert um 4 €.",
           "Im Mittel 5 €, denn weil ein Teil der Kinder nichts hat, halbiert sich der Wert von 10 €."],
          0,
          {1: "die Kinder mit 0 € nicht mitgezählt, obwohl auch sie zur Klasse gehören",
           2: "die Zahl der Kinder ohne Erspartes vom Mittelwert abgezogen, statt die Summe durch alle Kinder zu teilen",
           3: "den Mittelwert ohne Rechnung halbiert"},
          "Alle 20 Kinder zählen mit, auch die mit 0 €. Die Summe ist 16 · 10 = 160 €, geteilt durch 20 Kinder sind das 8 €.")
B.luecken("mittelwert", "korrektur", 2, "fehler", "fehler_detektiv",
          "Mia hat die Noten 2, 3, 2 und 5. Zeile 1: Die Summe der Noten ist 2 + 3 + 2 + 5 = 12. Zeile 2: Es sind vier Noten. Zeile 3: Der Mittelwert ist 12 : 3 = 4. Zeile 4: Mias Durchschnitt ist also 4. " + ZF + "wie groß ist der Mittelwert richtig?",
          "Fehler in Zeile □, Mittelwert richtig: □", [3, 3], ["3", "12 : 4"],
          [(2, 4, "12 : 3", "durch 3 statt durch die Zahl der Noten 4 geteilt"),
           (2, 12, "2 + 3 + 2 + 5", "die Summe als Mittelwert angegeben"),
           (1, 4, "4", "die Schlussfolgerung in Zeile 4 für den Fehler gehalten; sie übernimmt nur das falsche Ergebnis aus Zeile 3")],
          "Zeile 3 ist falsch: Man teilt durch die Anzahl der Noten, also durch 4. 12 : 4 = 3.")
B.auswahl("mittelwert", "korrektur", 2, "begruenden", None,
          "Gruppe A hat 10 Personen mit dem Mittelwert 8, Gruppe B hat 20 Personen mit dem Mittelwert 11. Welche Aussage über den Mittelwert aller 30 Personen stimmt?",
          ["Er beträgt 9,5, denn der Mittelwert liegt in der Mitte zwischen 8 und 11.",
           "Er liegt über 11, denn die größere Gruppe zählt doppelt.",
           "Er liegt näher bei 11, denn Gruppe B hat doppelt so viele Personen wie A.",
           "Er lässt sich nicht bestimmen, denn die Werte der einzelnen Personen sind nicht bekannt und es fehlen Angaben."],
          2,
          {0: "die beiden Mittelwerte einfach gemittelt, ohne die Gruppengrößen zu beachten",
           1: "übersehen, dass der Gesamtmittelwert immer zwischen den beiden Mittelwerten liegt",
           3: "übersehen, dass Mittelwert und Zahl der Personen schon die Summen der Gruppen festlegen"},
          "Gruppe A hat die Summe 10 · 8 = 80, Gruppe B die Summe 20 · 11 = 220. Zusammen 300 für 30 Personen: Mittelwert 10. Das liegt näher bei 11 als bei 8, weil Gruppe B größer ist.")
B.auswahl("mittelwert", "sicherung", 2, "begruenden", None,
          "Der Mittelwert der Zahlen 3, 5, 7 und 9 ist 6. Welche Veränderung lässt den Mittelwert unverändert bei 6?",
          ["Man streicht die 3.",
           "Man ersetzt die 3 durch 4 und die 9 durch 7.",
           "Man fügt eine weitere 6 hinzu.",
           "Man fügt die Zahlen 5 und 8 hinzu."],
          2,
          {0: ("die kleinste Zahl gestrichen: (5 + 7 + 9) : 3 = 7", "(5 + 7 + 9) : 3"),
           1: ("die Summe sinkt um 1: (4 + 5 + 7 + 7) : 4 = 5,75", "(4 + 5 + 7 + 7) : 4"),
           3: "die beiden neuen Zahlen liegen im Mittel bei 6,5, das hebt den Mittelwert an: 37 : 6 ≈ 6,17"},
          "Eine Zahl, die genau dem Mittelwert gleicht, ändert den Mittelwert nicht: (24 + 6) : 5 = 6. Bei den anderen Möglichkeiten ergibt sich 7, 5,75 und etwa 6,17.")
B.zahl("mittelwert", "sicherung", 3, "transfer", "anwenden",
       "Ein Kind legt jede Woche gleich viel mehr in die Spardose als in der Woche davor. In Woche 1 sind es 4 €, in Woche 9 sind es 20 €. Wie viel Euro legt es im Mittel pro Woche in die Spardose (Woche 1 bis Woche 9)?",
       12, "(4 + 20) : 2",
       [(24, "4 + 20", "Anfangs- und Endbetrag addiert und nicht durch 2 geteilt"),
        (16, "20 − 4", "den Unterschied von Anfang und Ende als Mittelwert genommen"),
        (2, "(20 − 4) : 8", "den Zuwachs pro Woche als Mittelwert angegeben")],
       "Bei gleichmäßigem Wachstum liegt der Mittelwert in der Mitte zwischen dem ersten und dem letzten Wert: (4 + 20) : 2 = 12. Probe: Die Beträge sind 4, 6, 8, 10, 12, 14, 16, 18, 20, ihre Summe ist 108 und 108 : 9 = 12.", einheit="€")
B.auswahl("mittelwert", "sicherung", 3, "begruenden", None,
          "Fünf Hunde wiegen 8 kg, 9 kg, 10 kg, 11 kg und 12 kg, im Mittel also 10 kg. Ein sechster Hund mit 60 kg kommt dazu. Welche Aussage über den neuen Mittelwert stimmt?",
          ["Er bleibt bei 10 kg, denn es kommt nur ein einzelner Wert dazu.",
           "Er beträgt 35 kg, denn man bildet den Mittelwert aus 10 kg und 60 kg: (10 + 60) : 2.",
           "Er sinkt unter 10 kg, denn nun sind mehr Werte vorhanden und der Durchschnitt wird dadurch kleiner.",
           "Er beträgt etwa 18 kg, denn (50 + 60) : 6 ist etwa 18,3 und das liegt über fünf Hunden."],
          3,
          {0: "nicht beachtet, dass die Summe stark wächst",
           1: "den alten Mittelwert wie einen einzelnen Wert behandelt",
           2: "mehr Werte mit sinkendem Mittelwert verwechselt"},
          "Neue Summe: 50 + 60 = 110 kg. 110 : 6 ≈ 18,3 kg. Das ist mehr als jeder der fünf ersten Hunde wiegt. Ein einzelner sehr großer Wert zieht den Mittelwert stark nach oben.")

# ---------------- mittel_rueckwaerts ----------------
B.zahl("mittel_rueckwaerts", "test", 3, "umkehr", "umkehren",
       "In einer Klasse mit 24 Kindern haben die Mädchen im Mittel 14 Punkte erreicht, die Jungen im Mittel 8 Punkte. Die ganze Klasse hat im Mittel 10 Punkte. Wie viele Mädchen sind in der Klasse?",
       8, "(24 · 10 − 24 · 8) : (14 − 8)",
       [(12, "24 : 2", "angenommen, Mädchen und Jungen seien gleich viele"),
        (16, "24 − 8", "die Zahl der Jungen statt der Mädchen angegeben"),
        (6, "14 − 8", "den Unterschied der beiden Mittelwerte als Anzahl genommen")],
       "Alle 24 Kinder zusammen haben 24 · 10 = 240 Punkte. Wären alle Kinder Jungen, wären es 24 · 8 = 192 Punkte. Jedes Mädchen bringt 14 − 8 = 6 Punkte mehr. Die fehlenden 240 − 192 = 48 Punkte ergeben 48 : 6 = 8 Mädchen. Probe: 8 · 14 + 16 · 8 = 112 + 128 = 240.")
B.zahl("mittel_rueckwaerts", "korrektur", 2, "parameter", None,
       "Fünf Zahlen haben den Mittelwert 12. Vier dieser Zahlen liegen 5 unter, 2 über, 6 über und 1 unter dem Mittelwert. Wie groß ist die fünfte Zahl?",
       10, "12 − ((2 + 6) − (5 + 1))",
       [(14, "12 + ((2 + 6) − (5 + 1))", "die fünfte Zahl über statt unter dem Mittelwert angesetzt"),
        (2, "(2 + 6) − (5 + 1)", "nur den Abstand der fünften Zahl zum Mittelwert angegeben")],
       "Die Abstände unter dem Mittelwert und über dem Mittelwert gleichen sich bei allen Zahlen zusammen aus. Über dem Mittelwert liegen 2 + 6 = 8, darunter 5 + 1 = 6. Die fünfte Zahl muss also 2 unter dem Mittelwert liegen: 12 − 2 = 10. Probe: Die Zahlen sind 7, 14, 18, 11 und 10, die Summe ist 60 und 60 : 5 = 12.")
B.luecken("mittel_rueckwaerts", "korrektur", 2, "fehler", "fehler_detektiv",
          "Eine Läuferin hat in vier Läufen im Mittel 50 Sekunden gebraucht. Im fünften Lauf will sie den Mittelwert aller fünf Läufe auf 48 Sekunden senken. Zeile 1: Der Mittelwert soll um 2 Sekunden sinken. Zeile 2: Also muss der fünfte Lauf 2 Sekunden schneller sein als der Mittelwert, 50 − 2 = 48 Sekunden. Zeile 3: Probe: Das passt zum Ziel 48. Zeile 4: Sie braucht im fünften Lauf 48 Sekunden. " + ZF + "wie lange darf der fünfte Lauf höchstens dauern?",
          "Fehler in Zeile □, richtig: □ Sekunden", [2, 40], ["2", "48 · 5 − 50 · 4"],
          [(2, 48, "50 − 2", "den Zielwert 48 selbst als Zeit des fünften Laufs genommen"),
           (2, 46, "50 − 2 · 2", "nur das Doppelte der Senkung von 50 abgezogen"),
           (1, 4, "4", "das Ergebnis in Zeile 4 für den Fehler gehalten; es folgt aus dem falschen Ansatz in Zeile 2")],
          "Zeile 2 ist falsch: Fünf Läufe müssen zusammen 5 · 48 = 240 Sekunden haben. Vier Läufe hatten 4 · 50 = 200 Sekunden. Der fünfte Lauf darf also 240 − 200 = 40 Sekunden dauern.")
B.auswahl("mittel_rueckwaerts", "korrektur", 2, "begruenden", None,
          "Der Mittelwert von vier Zahlen ist 10. Welche Aussage über diese vier Zahlen stimmt auf jeden Fall?",
          ["Mindestens eine der Zahlen ist größer als 10, denn der Mittelwert liegt in der Mitte der Zahlen.",
           "Mindestens eine der Zahlen ist mindestens 10, denn sonst läge der Mittelwert unter 10.",
           "Mindestens eine der Zahlen ist genau 10, denn der Mittelwert muss unter den Zahlen vorkommen.",
           "Höchstens zwei der Zahlen sind kleiner als 10, denn die Hälfte muss darüber liegen."],
          1,
          {0: "die vier Zahlen 10, 10, 10, 10 übersehen: Dann ist keine Zahl größer als 10",
           2: "angenommen, der Mittelwert müsse eine der Zahlen sein: 5, 15, 5, 15 hat den Mittelwert 10 ohne die Zahl 10",
           3: "die Mitte mit dem Mittelwert verwechselt: 9, 9, 9, 13 hat den Mittelwert 10 mit drei Zahlen unter 10"},
          "Wären alle vier Zahlen kleiner als 10, so wäre ihre Summe kleiner als 40 und der Mittelwert kleiner als 10. Also ist mindestens eine Zahl mindestens 10. Gegenbeispiele widerlegen die anderen Aussagen: 10, 10, 10, 10 / 5, 15, 5, 15 / 9, 9, 9, 13.")
B.luecken("mittel_rueckwaerts", "sicherung", 2, "darstellung", None,
          "Mia berechnet den Mittelwert der Zahlen 98, 101, 103, 99 und 104 über die Abweichungen von 100. Wie groß ist die Summe der fünf Abweichungen (mit Vorzeichen), und wie groß ist der Mittelwert der fünf Zahlen?",
          "Summe der Abweichungen: □, Mittelwert: □", [5, 101], ["−2 + 1 + 3 − 1 + 4", "100 + 5 : 5"],
          [(1, 505, "98 + 101 + 103 + 99 + 104", "die Zahlen selbst addiert statt ihrer Abweichungen"),
           (1, 11, "2 + 1 + 3 + 1 + 4", "die Abweichungen ohne Vorzeichen addiert"),
           (2, 1, "5 : 5", "die mittlere Abweichung als Mittelwert angegeben, ohne 100 dazuzuzählen")],
          "Die Abweichungen von 100 sind −2, +1, +3, −1 und +4. Ihre Summe ist 5, die mittlere Abweichung 5 : 5 = 1. Der Mittelwert ist 100 + 1 = 101.")
B.zahl("mittel_rueckwaerts", "sicherung", 3, "parameter", None,
       "Der Mittelwert von sechs Zahlen ist 20. Eine dieser Zahlen wird um 18 vergrößert, eine andere um 6 verkleinert, die übrigen vier bleiben gleich. Wie groß ist der neue Mittelwert?",
       22, "20 + (18 − 6) : 6",
       [(32, "20 + 18 − 6", "die Änderung der Summe zum Mittelwert addiert"),
        (23, "20 + 18 : 6", "nur die Vergrößerung beachtet und die Verkleinerung vergessen"),
        (24, "20 + (18 + 6) : 6", "die Verkleinerung wie eine Vergrößerung gerechnet")],
       "Die Summe der sechs Zahlen steigt um 18 − 6 = 12. Der Mittelwert steigt deshalb um 12 : 6 = 2 und ist 22.")
B.auswahl("mittel_rueckwaerts", "sicherung", 3, "begruenden", None,
          "Fünf Zahlen haben den Mittelwert 12. Man streicht die größte dieser Zahlen. Welche Aussage über den Mittelwert der übrigen vier Zahlen stimmt auf jeden Fall?",
          ["Er ist höchstens 12, denn die größte Zahl ist mindestens so groß wie der Mittelwert.",
           "Er liegt mindestens 1 unter 12, denn die größte Zahl fehlt jetzt und die übrigen Zahlen sind kleiner.",
           "Er bleibt 12, denn der Mittelwert hängt nicht davon ab, welche Zahl man streicht.",
           "Er steigt über 12, denn bei weniger Zahlen zählt jede einzelne Zahl stärker."],
          0,
          {1: "den Sonderfall übersehen, dass alle fünf Zahlen 12 sein können, dann bleibt der Mittelwert gleich",
           2: "geglaubt, Streichen ändere den Mittelwert nie: Bei 10, 11, 12, 13, 14 sinkt er auf 11,5",
           3: "geglaubt, die kleinere Anzahl lasse den Mittelwert steigen"},
          "Die größte Zahl ist mindestens so groß wie der Mittelwert 12. Streicht man sie, ist der Rest im Mittel höchstens 12. Sind alle Zahlen gleich 12, bleibt der Mittelwert 12; bei 10, 11, 12, 13, 14 sinkt er auf 11,5.")
